package in.sevasetu.amc.web;
import in.sevasetu.amc.security.CurrentUser;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.http.*;import org.springframework.jdbc.core.simple.JdbcClient;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.bind.annotation.*;import org.springframework.web.server.ResponseStatusException;import java.math.BigDecimal;import java.time.Instant;import java.util.*;
@RestController @RequestMapping("/api/owner/notifications") @PreAuthorize("hasAnyRole('OWNER','ADMIN')") public class OwnerNotificationController{private final JdbcClient db;public OwnerNotificationController(JdbcClient db){this.db=db;}
 public record Settings(int purchaseReminderDays,BigDecimal premiumCustomerThreshold,boolean automaticNotifications,boolean whatsappEnabled,String whatsappNumber,boolean facebookConnected,String facebookPageName){}
 public record Update(@Min(1)@Max(365)int purchaseReminderDays,@DecimalMin("0")BigDecimal premiumCustomerThreshold,boolean automaticNotifications,boolean whatsappEnabled,String whatsappNumber){}
 public record Page(List<Map<String,Object>> content,int page,int totalPages,long totalElements){} public record Message(@NotEmpty List<UUID> customerIds,@NotBlank String message){} public record Result(boolean sent,boolean queued,String status,int customers){}
 @GetMapping("/settings") Settings settings(@AuthenticationPrincipal CurrentUser u){CustomerController.tenant(u);ensure(u.tenantId());var row=db.sql("select purchase_reminder_days,premium_customer_threshold,automatic_notifications,whatsapp_enabled,whatsapp_number from amcservice.tenant_automation_settings where tenant_id=:t").param("t",u.tenantId()).query().listOfRows().getFirst();var fb=db.sql("select external_account_name from amcservice.social_connections where tenant_id=:t and platform='FACEBOOK' and active").param("t",u.tenantId()).query(String.class).optional();return new Settings((Integer)row.get("purchase_reminder_days"),(BigDecimal)row.get("premium_customer_threshold"),(Boolean)row.get("automatic_notifications"),(Boolean)row.get("whatsapp_enabled"),(String)row.get("whatsapp_number"),fb.isPresent(),fb.orElse(null));}
 @PutMapping("/settings") void update(@AuthenticationPrincipal CurrentUser u,@Valid@RequestBody Update r){CustomerController.tenant(u);ensure(u.tenantId());db.sql("update amcservice.tenant_automation_settings set purchase_reminder_days=:days,premium_customer_threshold=:premium,automatic_notifications=:auto,whatsapp_enabled=:enabled,whatsapp_number=:phone,updated_at=now() where tenant_id=:t").param("days",r.purchaseReminderDays()).param("premium",r.premiumCustomerThreshold()).param("auto",r.automaticNotifications()).param("enabled",r.whatsappEnabled()).param("phone",r.whatsappNumber()).param("t",u.tenantId()).update();}
 @GetMapping("/customers") Page customers(@AuthenticationPrincipal CurrentUser u,@RequestParam(defaultValue="0")@Min(0)int page){CustomerController.tenant(u);ensure(u.tenantId());var threshold=db.sql("select premium_customer_threshold from amcservice.tenant_automation_settings where tenant_id=:t").param("t",u.tenantId()).query(BigDecimal.class).single();var total=db.sql("select count(*) from amcservice.customers where tenant_id=:t and lifetime_value>=:v").param("t",u.tenantId()).param("v",threshold).query(Long.class).single();var rows=db.sql("select c.id,c.name,c.phone,c.lifetime_value,max(o.created_at) last_purchase_at,count(o.id) purchase_count from amcservice.customers c left join amcservice.orders o on o.customer_id=c.id where c.tenant_id=:t and c.lifetime_value>=:v group by c.id order by c.lifetime_value desc,c.name limit 5 offset :offset").param("t",u.tenantId()).param("v",threshold).param("offset",page*5).query().listOfRows();return new Page(rows,page,(int)Math.ceil(total/5.0),total);}
 @PostMapping("/send") @Transactional Result send(@AuthenticationPrincipal CurrentUser u,@Valid@RequestBody Message r){CustomerController.tenant(u);ensure(u.tenantId());var settings=settings(u);int accepted=0;for(var id:r.customerIds()){var exists=db.sql("select count(*) from amcservice.customers where id=:id and tenant_id=:t").param("id",id).param("t",u.tenantId()).query(Integer.class).single()>0;if(exists){db.sql("insert into amcservice.notification_jobs(id,tenant_id,customer_id,kind,scheduled_for,status,message,idempotency_key) values(:id,:t,:c,'MANUAL',now(),'PENDING',:message,:key) on conflict(idempotency_key) do nothing").param("id",UUID.randomUUID()).param("t",u.tenantId()).param("c",id).param("message",r.message()).param("key",u.tenantId()+":manual:"+id+":"+Instant.now().toEpochMilli()).update();accepted++;}}return settings.whatsappEnabled()?new Result(false,true,"QUEUED_FOR_WHATSAPP",accepted):new Result(false,true,"QUEUED_WHATSAPP_NOT_CONFIGURED",accepted);}
 private void ensure(UUID tenant){db.sql("insert into amcservice.tenant_automation_settings(tenant_id) values(:t) on conflict do nothing").param("t",tenant).update();}
}
